`timescale 1ns/1ps
module tb_wishbone_apb_bridge;logic clk=0,rstn=0,cyc,stb,we,ack,err,psel,pen,pw,prdy,perr;logic[31:0]adr,wd,rd,pa,pwd,prd;logic[3:0]bs,ps;wishbone_apb_bridge dut(.clk_i(clk),.rst_ni(rstn),.wb_cyc_i(cyc),.wb_stb_i(stb),.wb_we_i(we),.wb_adr_i(adr),.wb_dat_i(wd),.wb_sel_i(bs),.wb_dat_o(rd),.wb_ack_o(ack),.wb_err_o(err),.psel_o(psel),.penable_o(pen),.pwrite_o(pw),.paddr_o(pa),.pwdata_o(pwd),.pstrb_o(ps),.prdata_i(prd),.pready_i(prdy),.pslverr_i(perr));always#5 clk=~clk;
initial begin cyc=0;stb=0;we=0;adr=0;wd=0;bs=0;prd=32'h9876;prdy=0;perr=0;repeat(2)@(negedge clk);rstn=1;cyc=1;stb=1;we=1;adr=32'h100;wd=32'h1234;bs=4'hf;@(negedge clk);if(!psel||pen)$fatal(1,"setup");@(negedge clk);if(!pen)$fatal(1,"access");repeat(2)@(negedge clk);prdy=1;@(negedge clk);#1;if(!ack||err)$fatal(1,"ack");cyc=0;stb=0;prdy=0;@(negedge clk);cyc=1;stb=1;perr=1;repeat(2)@(negedge clk);prdy=1;@(negedge clk);#1;if(!err||ack)$fatal(1,"error");$display("WISHBONE_APB_BRIDGE_PASS");$finish;end endmodule
